#include <pthread.h>
#include <openssl/evp.h>

#define N 40960000
static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec/1e9; }

unsigned char *pt, *ct, *key, *nonce;

void chacha_encrypt(unsigned char *out, const unsigned char *in, size_t len, unsigned int ctr){
    unsigned char nonce16[16]={0};
    memcpy(nonce16+4, nonce, 12);
    nonce16[0]=ctr&0xff; nonce16[1]=(ctr>>8)&0xff; nonce16[2]=(ctr>>16)&0xff; nonce16[3]=(ctr>>24)&0xff;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, NULL, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce16);
    int l=0;
    EVP_EncryptUpdate(ctx, out, &l, in, len);
    EVP_EncryptFinal_ex(ctx, out+l, &l);
    EVP_CIPHER_CTX_free(ctx);
}

typedef struct { long id; int t; } arg_t;
void* chacha_worker(void* a){
    arg_t *aa = (arg_t*)a;
    size_t chunk = N/aa->t;
    size_t off = aa->id*chunk;
    unsigned int ctr = 1 + (unsigned int)(off/64);
    for(int i=0;i<10;i++) chacha_encrypt(ct+off, pt+off, chunk, ctr);
    return NULL;
}

int main(){
    pt = malloc(N); ct = malloc(N); key = malloc(32); nonce = malloc(12);
    for(size_t i=0;i<N;i++) pt[i]=i&0xff;
    for(int i=0;i<32;i++) key[i]=i;
    for(int i=0;i<12;i++) nonce[i]=i;
    // reference single-thread full
    unsigned char *ref = malloc(N);
    chacha_encrypt(ref, pt, N, 1);
    // single thread timing
    double t0=now();
    for(int i=0;i<10;i++) chacha_encrypt(ct, pt, N, 1);
    double t1=now();
    printf("single: %.4f s/op, %.2f GB/s\n", (t1-t0)/10, N/((t1-t0)/10)/1e9);
    // multi
    for(int t=2;t<=12;t+=2){
        pthread_t th[12]; arg_t args[12];
        t0=now();
        for(long i=0;i<t;i++){ args[i].id=i; args[i].t=t; pthread_create(&th[i],NULL,chacha_worker,(void*)&args[i]); }
        for(int i=0;i<t;i++) pthread_join(th[i],NULL);
        t1=now();
        int ok = memcmp(ct, ref, N)==0;
        printf("%d threads: %.4f s/op, %.2f GB/s, correct=%d\n", t, (t1-t0)/10, N/((t1-t0)/10)/1e9, ok);
    }
    return 0;
}
