{"command":"cd /private/var/folders/bd/8xxg4c4j4rqc_6fqwvpxwnd80000gn/T/algotuneprobe_lk9g25jo/ep0; cat > solver.c <<'EOF'
#include <openssl/evp.h>
#include <openssl/core_names.h>
#include <openssl/params.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>

typedef struct {
    const uint8_t *key, *nonce, *pt;
    uint8_t *ct;
    size_t off, len;
} chacha_arg;

static void* chacha_worker(void *a) {
    chacha_arg *arg = (chacha_arg*)a;
    uint8_t nonce16[16] = {0};
    memcpy(nonce16 + 4, arg->nonce, 12);
    uint32_t ctr = 1 + (uint32_t)(arg->off / 64);
    nonce16[0] = ctr & 0xff; nonce16[1] = (ctr>>8)&0xff; nonce16[2]=(ctr>>16)&0xff; nonce16[3]=(ctr>>24)&0xff;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, NULL, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, arg->key, nonce16);
    int l = 0;
    EVP_EncryptUpdate(ctx, arg->ct + arg->off, &l, arg->pt + arg->off, arg->len);
    EVP_EncryptFinal_ex(ctx, arg->ct + arg->off + l, &l);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

void chacha20_encrypt_parallel(const uint8_t *key, const uint8_t *nonce, const uint8_t *pt, uint8_t *ct, size_t n, int nthreads) {
    pthread_t th[16];
    chacha_arg args[16];
    size_t chunk = (n / nthreads / 64) * 64;
    if (chunk == 0) chunk = 64;
    for (int i = 0; i < nthreads; i++) {
        args[i].key = key; args[i].nonce = nonce; args[i].pt = pt; args[i].ct = ct;
        args[i].off = i * chunk;
        args[i].len = (i == nthreads - 1) ? (n - i*chunk) : chunk;
        if (args[i].len <= 0) { args[i].len = 0; }
        pthread_create(&th[i], NULL, chacha_worker, &args[i]);
    }
    for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
}

static void chacha20_keystream(const uint8_t *key, const uint8_t *nonce, uint32_t ctr, uint8_t *out, size_t n) {
    uint8_t nonce16[16] = {0};
    memcpy(nonce16 + 4, nonce, 12);
    nonce16[0] = ctr & 0xff; nonce16[1] = (ctr>>8)&0xff; nonce16[2]=(ctr>>16)&0xff; nonce16[3]=(ctr>>24)&0xff;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, NULL, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce16);
    uint8_t *zeros = calloc(n, 1);
    int l = 0;
    EVP_EncryptUpdate(ctx, out, &l, zeros, n);
    EVP_EncryptFinal_ex(ctx, out + l, &l);
    free(zeros);
    EVP_CIPHER_CTX_free(ctx);
}

void solve(const uint8_t *key, const uint8_t *nonce, const uint8_t *pt, size_t pt_len,
           const uint8_t *aad, size_t aad_len, uint8_t *ct, uint8_t *tag, int nthreads) {
    uint8_t polykey[32];
    chacha20_keystream(key, nonce, 0, polykey, 32);
    chacha20_encrypt_parallel(key, nonce, pt, ct, pt_len, nthreads);

    EVP_MAC *mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    EVP_MAC_CTX *ctx = EVP_MAC_CTX_new(mac);
    OSSL_PARAM params[2];
    params[0] = OSSL_PARAM_construct_octet_string(OSSL_MAC_PARAM_KEY, polykey, 32);
    params[1] = OSSL_PARAM_construct_end();
    EVP_MAC_init(ctx, polykey, 32, params);
    uint8_t zero[16] = {0};
    EVP_MAC_update(ctx, aad, aad_len);
    size_t pad = (16 - (aad_len % 16)) % 16;
    EVP_MAC_update(ctx, zero, pad);
    EVP_MAC_update(ctx, ct, pt_len);
    pad = (16 - (pt_len % 16)) % 16;
    EVP_MAC_update(ctx, zero, pad);
    uint8_t lens[16];
    uint64_t la = aad_len, lc = pt_len;
    for (int i = 0; i < 8; i++) lens[i] = (la >> (8*i)) & 0xff;
    for (int i = 0; i < 8; i++) lens[8+i] = (lc >> (8*i)) & 0xff;
    EVP_MAC_update(ctx, lens, 16);
    size_t taglen = 16;
    EVP_MAC_final(ctx, tag, &taglen, 16);
    EVP_MAC_CTX_free(ctx);
    EVP_MAC_free(mac);
}
EOF
